use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::HashMap;
use std::io::{self, Write};

const BILLING_UNIT_SECONDS: i64 = 15 * 60;

pub struct BillCommand;

fn rounded_billable_totals(entries: &[TimeEntry]) -> Vec<(String, i64)> {
    let mut totals = HashMap::<String, i64>::new();

    for entry in entries {
        if !entry.billable || entry.stop.is_none() || entry.duration <= 0 {
            continue;
        }

        let rounded_duration = ((entry.duration + BILLING_UNIT_SECONDS - 1) / BILLING_UNIT_SECONDS)
            * BILLING_UNIT_SECONDS;
        let project_name = entry
            .project
            .as_ref()
            .map(|project| project.name.clone())
            .unwrap_or_else(|| "No Project".to_string());
        *totals.entry(project_name).or_default() += rounded_duration;
    }

    let mut totals: Vec<_> = totals.into_iter().collect();
    totals.sort_by(|(name_a, seconds_a), (name_b, seconds_b)| {
        seconds_b.cmp(seconds_a).then_with(|| name_a.cmp(name_b))
    });
    totals
}

fn write_totals(mut writer: impl Write, totals: &[(String, i64)]) -> io::Result<()> {
    if totals.is_empty() {
        writeln!(writer, "(no data)")?;
        return Ok(());
    }

    let total_seconds: i64 = totals.iter().map(|(_, seconds)| seconds).sum();
    for (project, seconds) in totals {
        writeln!(writer, "{seconds}s  {project}")?;
    }
    writeln!(writer, "{total_seconds}s  Total")
}

impl BillCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        write_totals(io::stdout(), &rounded_billable_totals(&entries))
            .map_err(|error| Box::new(error) as Box<dyn std::error::Error + Send>)?;
        Ok(())
    }
}

